import React from 'react';
import { Image } from 'react-native';

// Versão para o Expo Snack: o logo vai embutido no código (sem arquivo de imagem).
const LOGO_URI = 'data:image/png;base64,';

export default function BrandLogo({ size = 96 }) {
  return <Image source={{ uri: LOGO_URI }} style={{ width: size, height: size }} resizeMode="contain" />;
}
